(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-867":{scenario:{company:"Học viện Anh ngữ Thiên Lý",supervisor:{name:"Ngô Thanh Bình",role:{vi:"Trưởng bộ môn IELTS",en:"Head of IELTS Department"}},ref_code:"IEL-3384",title:{vi:"Đúng tiêu chí. Đúng điểm tổng. Đúng sự thật.",en:"Right criterion. Right overall band. Right truth."},brief:{vi:"Bạn hoàn thiện phiếu kết quả thi thử IELTS IEL-3384 của một học viên lớp mục tiêu 6.5+. Điểm từng kỹ năng: Nghe 8.0, Đọc 6.5, Viết 6.0, Nói 6.5. Đề Viết Task 2 yêu cầu bàn cả nguyên nhân và giải pháp, nhưng bài chỉ phân tích nguyên nhân. Đối chiếu phiếu nhận xét nháp với khung tiêu chí và quy tắc làm tròn đã duyệt, sửa tiêu chí ghi nhận lỗi chính của bài Viết và điểm tổng (overall), rồi lập báo cáo có căn cứ.",en:"You are finalizing IELTS mock test report IEL-3384 for a learner in the 6.5+ target class. Skill scores: Listening 8.0, Reading 6.5, Writing 6.0, Speaking 6.5. The Writing Task 2 prompt asks for both causes and solutions, but the essay only discusses causes. Compare the draft feedback sheet with the approved criteria and rounding rules, correct the main criterion for the Writing issue and the overall band, then write an evidence-based report."},reference_title:{vi:"Khung tiêu chí chấm & quy tắc làm tròn đã duyệt · IEL-3384",en:"Approved marking criteria & rounding rules · IEL-3384"},fields:[{id:"W_CRITERION",label:{vi:"Tiêu chí ghi nhận lỗi chính bài Viết",en:"Main Writing criterion affected"},initial:"COHERENCE",expected:"TASK-RESPONSE",choices:["COHERENCE","TASK-RESPONSE","LEXICAL"],reference:"Khung tiêu chí Writing Task 2",hint:{vi:"Bài không trả lời đủ mọi phần của đề là vấn đề về mức độ đáp ứng yêu cầu đề bài, không phải tính liên kết.",en:"Failing to address every part of the prompt is about meeting task requirements, not cohesion."}},{id:"OVERALL",label:{vi:"Điểm tổng (overall band)",en:"Overall band score"},initial:"6.5",expected:"7.0",reference:"Bảng quy đổi điểm tổng",ref_value:{vi:"Nghe 8.0, Đọc 6.5, Viết 6.0, Nói 6.5; áp dụng quy tắc làm tròn của khung điểm",en:"Listening 8.0, Reading 6.5, Writing 6.0, Speaking 6.5; apply the band rounding rule"},hint:{vi:"Tính trung bình cộng 4 kỹ năng rồi xem phần lẻ: không được cắt bỏ phần lẻ.",en:"Average the four skills and check the decimal: never simply truncate it."}}],sop32:{vi:"Điểm tổng = trung bình cộng 4 kỹ năng, làm tròn đến nửa band gần nhất; phần lẻ .25 làm tròn lên .5, phần lẻ .75 làm tròn lên band nguyên kế tiếp.",en:"Overall band = mean of the four skills rounded to the nearest half band; a .25 decimal rounds up to .5 and a .75 decimal rounds up to the next whole band."},context:{label:"SỔ ĐIỂM THI THỬ / IEL-3384",metrics:[{label:{vi:"Nghe / Đọc",en:"Listening / Reading"},value:"8.0 / 6.5"},{label:{vi:"Viết / Nói",en:"Writing / Speaking"},value:"6.0 / 6.5"},{label:{vi:"Mục tiêu lớp",en:"Class target"},value:"6.5+"}]},crisis:{vi:"Quản lý tư vấn nhắn: “Ghi overall 7.5 cho học viên này để phụ huynh yên tâm đóng tiếp khóa sau. Mình đưa luôn tên và điểm lên bảng vàng quảng cáo, chưa cần hỏi ý kiến gia đình.”",en:"The admissions manager writes: “Put overall 7.5 for this learner so the parents keep paying for the next course. We will also post the name and score on our honor board ad without asking the family yet.”"},options:{safe:{vi:"Từ chối nâng điểm, báo đúng điểm làm tròn theo khung kèm kế hoạch cải thiện Task Response, báo Trưởng bộ môn; chỉ quảng cáo kết quả thật khi có sự đồng ý bằng văn bản của gia đình.",en:"Refuse to inflate the score, report the correctly rounded band with a Task Response improvement plan, inform the Head of Department; publish real results only with the family's written consent."},shortcut:{vi:"Ghi 7.5 vì chỉ là bài thi thử, không ảnh hưởng điểm thi thật.",en:"Write 7.5 because it is only a mock test and does not affect the real exam."},wait:{vi:"Chưa trả kết quả và chờ quản lý tư vấn tự trao đổi với phụ huynh.",en:"Hold the result and wait for the admissions manager to talk to the parents."}},questions:{vi:["Vì sao lỗi chính thuộc TASK-RESPONSE và điểm tổng là 7.0? Trình bày phép tính trung bình và quy tắc làm tròn.","Báo điểm thi thử cao hơn thực tế gây hại gì cho học viên và trung tâm? Bạn trao đổi với phụ huynh thế nào?"],en:["Why is the main issue TASK-RESPONSE and why is the overall band 7.0? Show the average and the rounding rule.","How does reporting an inflated mock score harm the learner and the school? How do you talk to the parents?"]},hints:{vi:["Đặt phiếu nhận xét nháp cạnh khung tiêu chí Writing và gạch chân yêu cầu nào của đề chưa được trả lời.","Áp dụng SOP mục 3.2: cộng 4 kỹ năng, chia 4 rồi áp quy tắc làm tròn cho phần lẻ.","Đọc lại SOP mục 4.2: kết quả đánh giá phải trung thực; dùng tên và điểm học viên cho quảng cáo cần sự đồng ý."],en:["Place the draft feedback next to the Writing criteria and underline which part of the prompt was not answered.","Apply SOP 3.2: add the four skills, divide by 4, then apply the rounding rule to the decimal.","Re-read SOP 4.2: results must be honest; using a learner's name and score in ads needs consent."]}},learning:{summary:{vi:"Giáo viên tiếng Anh quốc tế (TESOL/IELTS) thiết kế và giảng dạy các khóa tiếng Anh giao tiếp, học thuật và luyện thi, chẩn đoán trình độ, chấm chữa bài theo tiêu chí, phản hồi cá nhân hóa và theo dõi tiến bộ của học viên. Nghề đòi hỏi năng lực ngôn ngữ cao, phương pháp dạy hiện đại, hiểu sâu khung đánh giá và sự trung thực tuyệt đối khi báo cáo kết quả.",en:"A TESOL/IELTS instructor designs and teaches general, academic and test preparation English courses, diagnoses levels, marks against criteria, gives personalized feedback and tracks learner progress. The job requires high language proficiency, modern teaching methods, deep knowledge of assessment frameworks and absolute honesty in reporting results."},responsibilities:{vi:["Kiểm tra đầu vào, xếp lớp và xây dựng lộ trình học theo mục tiêu từng học viên.","Soạn giáo án theo đường hướng giao tiếp và nhiệm vụ, kết hợp 4 kỹ năng Nghe, Nói, Đọc, Viết.","Chấm chữa bài Viết và Nói theo tiêu chí công bố, phản hồi cụ thể, có ví dụ sửa.","Tổ chức thi thử định kỳ, tính điểm đúng quy tắc và báo cáo tiến bộ cho học viên, phụ huynh.","Tham gia sinh hoạt chuyên môn, dự giờ, chuẩn hóa chấm điểm giữa các giáo viên."],en:["Run placement tests, assign classes and build learning paths for each learner's goal.","Plan lessons using communicative and task-based approaches across Listening, Speaking, Reading and Writing.","Mark Writing and Speaking against published criteria with specific, example-based feedback.","Run regular mock tests, score them correctly and report progress to learners and parents.","Join professional development, peer observation and marker standardization sessions."]},competencies:[{name:{vi:"Năng lực ngôn ngữ",en:"Language proficiency"},desc:{vi:"Sử dụng tiếng Anh chuẩn xác ở trình độ cao, làm mẫu phát âm, ngữ pháp và từ vựng học thuật.",en:"Use highly accurate English and model pronunciation, grammar and academic vocabulary."}},{name:{vi:"Phương pháp giảng dạy",en:"Teaching methodology"},desc:{vi:"Áp dụng CLT, TBLT, dạy phân hóa và quản lý lớp học tích cực.",en:"Apply CLT, TBLT, differentiated instruction and active classroom management."}},{name:{vi:"Đánh giá theo tiêu chí",en:"Criterion-based assessment"},desc:{vi:"Chấm nhất quán theo mô tả band, xác định đúng tiêu chí bị ảnh hưởng và làm tròn điểm đúng quy tắc.",en:"Mark consistently to band descriptors, identify the affected criterion and round scores correctly."}},{name:{vi:"Phản hồi & huấn luyện",en:"Feedback & coaching"},desc:{vi:"Đưa phản hồi cụ thể, khả thi và theo dõi tiến bộ bằng dữ liệu bài làm.",en:"Give specific, actionable feedback and track progress with work samples."}},{name:{vi:"Liêm chính nghề nghiệp",en:"Professional integrity"},desc:{vi:"Báo cáo điểm trung thực, không dùng đề thi bị lộ và bảo vệ thông tin cá nhân học viên.",en:"Report scores honestly, never use leaked test papers and protect learners' personal data."}}],knowledge:{vi:["Khung tham chiếu chung châu Âu về ngôn ngữ (CEFR) với 6 bậc A1 đến C2.","Khung năng lực ngoại ngữ 6 bậc dùng cho Việt Nam ban hành kèm Thông tư 01/2014/TT-BGDĐT, tương thích CEFR.","Bốn tiêu chí chấm Writing IELTS: Task Achievement/Response, Coherence and Cohesion, Lexical Resource, Grammatical Range and Accuracy.","Quy tắc làm tròn điểm tổng IELTS đến nửa band gần nhất (.25 lên .5, .75 lên band nguyên kế tiếp).","Đường hướng giao tiếp (CLT), dạy học theo nhiệm vụ (TBLT) và đánh giá quá trình."],en:["The Common European Framework of Reference for Languages (CEFR) with six levels from A1 to C2.","Vietnam's six-level Foreign Language Proficiency Framework issued with Circular 01/2014/TT-BGDDT, aligned with CEFR.","The four IELTS Writing criteria: Task Achievement/Response, Coherence and Cohesion, Lexical Resource, Grammatical Range and Accuracy.","IELTS overall band rounding to the nearest half band (.25 up to .5, .75 up to the next whole band).","Communicative Language Teaching (CLT), Task-Based Language Teaching (TBLT) and formative assessment."]},tools:["Hệ thống quản lý học tập (LMS)","Bộ mô tả band điểm và rubric chấm","Phần mềm ghi âm chấm Nói","Kho đề luyện thi có bản quyền","Bảng tính sổ điểm và theo dõi tiến bộ","Bảng tương tác lớp học"],kpis:{vi:["Mức tăng band trung bình của học viên sau mỗi khóa.","Tỷ lệ học viên đạt mục tiêu đầu ra cam kết.","Độ lệch điểm chấm so với giám khảo chuẩn hóa (mục tiêu không quá 0.5 band).","Điểm hài lòng của học viên và tỷ lệ học tiếp khóa sau."],en:["Average band gain per course.","Share of learners reaching the committed target score.","Marking deviation from the standardized examiner (target no more than 0.5 band).","Learner satisfaction and re-enrollment rate."]},day:[{time:"08:00",vi:"Chuẩn bị giáo án, học liệu và nhiệm vụ nói theo chủ đề cho lớp sáng.",en:"Prepare the lesson plan, materials and speaking tasks for the morning class."},{time:"09:00",vi:"Dạy lớp Writing học thuật: phân tích đề, lập dàn ý và luyện viết đoạn thân bài.",en:"Teach academic Writing: analyze prompts, outline and practice body paragraphs."},{time:"13:30",vi:"Chấm chữa bài Task 2, ghi phản hồi theo 4 tiêu chí và ví dụ câu sửa.",en:"Mark Task 2 essays with feedback on the four criteria and corrected examples."},{time:"16:00",vi:"Phỏng vấn Speaking thử, ghi âm và chấm theo mô tả band.",en:"Run mock Speaking interviews, record them and score against band descriptors."},{time:"18:30",vi:"Dạy lớp tối và cập nhật sổ điểm, báo cáo tiến bộ cho phụ huynh.",en:"Teach the evening class and update the gradebook and progress reports for parents."}],mistakes:{vi:["Cắt bỏ phần lẻ khi tính điểm tổng thay vì làm tròn đúng quy tắc nửa band.","Ghi lỗi trả lời thiếu ý của đề vào tiêu chí liên kết, khiến học viên luyện sai trọng tâm.","Nâng điểm thi thử để giữ chân học viên hoặc làm quảng cáo, gây kỳ vọng sai và mất uy tín."],en:["Truncating the decimal of the overall band instead of applying the half-band rounding rule.","Logging an incomplete answer to the prompt under cohesion, so the learner practices the wrong focus.","Inflating mock scores to retain learners or for advertising, creating false expectations and losing trust."]},career:[{vi:"Trợ giảng tiếng Anh",en:"Teaching assistant"},{vi:"Giáo viên tiếng Anh TESOL/IELTS",en:"TESOL/IELTS instructor"},{vi:"Giáo viên cao cấp & điều phối chuyên môn",en:"Senior teacher & academic coordinator"},{vi:"Giám đốc học thuật trung tâm ngoại ngữ",en:"Director of studies"}],glossary:[{term:"Band descriptor",vi:"Bảng mô tả năng lực tương ứng từng mức band cho mỗi tiêu chí chấm.",en:"A table describing performance at each band level for every criterion."},{term:"Task Response",vi:"Tiêu chí đánh giá mức độ bài viết trả lời đầy đủ, phát triển ý và giữ lập trường rõ ràng.",en:"The criterion judging how fully an essay addresses the prompt, develops ideas and holds a clear position."},{term:"CEFR",vi:"Khung tham chiếu ngôn ngữ chung châu Âu, mô tả năng lực từ A1 đến C2.",en:"Common European Framework of Reference, describing proficiency from A1 to C2."},{term:"TBLT",vi:"Dạy học theo nhiệm vụ: học viên dùng ngôn ngữ để hoàn thành nhiệm vụ có ý nghĩa.",en:"Task-based teaching where learners use language to complete meaningful tasks."},{term:"Standardization",vi:"Chuẩn hóa chấm: các giáo viên chấm bài mẫu, so sánh và thống nhất cách áp dụng tiêu chí.",en:"Markers score sample scripts, compare and agree on how to apply criteria."}],quiz:[{q:{vi:"Học viên đạt Nghe 6.5, Đọc 6.5, Viết 5.5, Nói 6.5. Điểm tổng IELTS là bao nhiêu?",en:"A learner scores Listening 6.5, Reading 6.5, Writing 5.5, Speaking 6.5. What is the overall band?"},options:{vi:["6.0","6.25","5.5","6.5"],en:["6.0","6.25","5.5","6.5"]},answer:3,explain:{vi:"Trung bình = 25 / 4 = 6.25; phần lẻ .25 làm tròn lên 6.5.",en:"Mean = 25 / 4 = 6.25; a .25 decimal rounds up to 6.5."}},{q:{vi:"Theo Khung năng lực ngoại ngữ 6 bậc của Việt Nam, Bậc 4 tương đương trình độ CEFR nào?",en:"In Vietnam's six-level framework, Level 4 is equivalent to which CEFR level?"},options:{vi:["B1","B2","C1","A2"],en:["B1","B2","C1","A2"]},answer:1,explain:{vi:"Khung 6 bậc tương thích CEFR: Bậc 1-6 ứng với A1, A2, B1, B2, C1, C2, nên Bậc 4 là B2.",en:"The six levels align with CEFR A1 to C2, so Level 4 equals B2."}},{q:{vi:"Bài Task 2 chỉ trả lời một trong hai câu hỏi của đề. Tiêu chí nào bị ảnh hưởng trực tiếp nhất?",en:"A Task 2 essay answers only one of the two questions. Which criterion is most directly affected?"},options:{vi:["Task Response","Lexical Resource","Grammatical Range and Accuracy","Coherence and Cohesion"],en:["Task Response","Lexical Resource","Grammatical Range and Accuracy","Coherence and Cohesion"]},answer:0,explain:{vi:"Không đáp ứng đủ các phần của đề là hạn chế thuộc Task Response.",en:"Not addressing all parts of the prompt is a Task Response limitation."}},{q:{vi:"Quản lý yêu cầu nâng điểm thi thử để làm quảng cáo. Cách xử lý đúng là gì?",en:"A manager asks you to inflate a mock score for advertising. What is right?"},options:{vi:["Nâng điểm vì là thi thử","Nâng nửa band cho hợp lý","Từ chối, báo điểm thật, báo cáo và chỉ quảng cáo khi có kết quả thật và sự đồng ý","Không chấm bài nữa"],en:["Inflate it since it is a mock","Add half a band to look reasonable","Refuse, report the true score, escalate and advertise only real results with consent","Stop marking the test"]},answer:2,explain:{vi:"Điểm sai lệch gây hiểu nhầm cho học viên, phụ huynh và người tiêu dùng; quảng cáo phải dựa trên kết quả thật, có đồng ý.",en:"False scores mislead learners, parents and consumers; ads must use real, consented results."}}],tools_en:["Learning management system (LMS)","Band descriptors and scoring rubrics","Recording software for Speaking assessment","Licensed practice test bank","Gradebook and progress tracking spreadsheet","Interactive whiteboard"]}}})})(window.KKR);
